import React, { useState, useEffect } from 'react'; // 1. IMPORT THESE
import { useOutletContext } from 'react-router-dom';

const Cloud_SubPage = ({ index, title }) => {
  const context = useOutletContext();
  const cloudData = context?.cloud?.data;
  
  // 2. Local state initialization
  const [data, setData] = useState(cloudData ? cloudData[index] : null);

  // 3. Listen for changes in context so the component updates when you click "Sync"
  useEffect(() => {
    if (cloudData && cloudData[index]) {
      setData(cloudData[index]);
    }
  }, [cloudData, index]); 

  return (
    <div className="summary-box">
      <h3>{title}</h3>
      {data ? (
        <div className="telemetry-data">
          <p className="status-badge">● Status: {data.status}</p>
          <pre className="json-view">{JSON.stringify(data, null, 2)}</pre>
        </div>
      ) : (
        <div className="empty-state">
          <p>Sync from the Infrastructure Dashboard to see data stream.</p>
        </div>
      )}
    </div>
  );
};

export default Cloud_SubPage;
